text(await tools.exec_command({cmd:"python - <<'PY'
import json, pathlib
from PIL import Image
runs=[]
for p in pathlib.Path('/app/runs').glob('*/meta.json'):
 m=json.loads(p.read_text());runs.append((m['control_steps'],m['calls'],p.parent.name,m))
runs.sort();history=[];last=0
for steps,call,name,m in runs:
 if steps>last:
  proprio=dict(zip(m['proprio']['layout'],m['proprio']['now']))
  action=[proprio[k] for k in ['cmd_arm_dx','cmd_arm_dy','cmd_arm_dz','cmd_arm_drx','cmd_arm_dry','cmd_arm_drz','cmd_grip','cmd_base_x','cmd_base_y','cmd_base_yaw','cmd_torso','cmd_hybrid_mode']]
  history.append({'label':name,'steps':steps-last,'action':action});last=steps
pathlib.Path('/app/output/action_history.json').write_text(json.dumps(history,indent=2))
Image.open('/app/runs/final_stable/last/robot0_eye_in_hand.jpg').resize((960,720)).save('/app/output/final_eye.jpg')
print('Recorded',last,'control steps')
PY","max_output_tokens":1000}));
